using System.Threading; using System.Threading.Tasks; using System.Data; using System.Data.SQLite; using Dapper; using AlKhayal.Application.Authentication;
namespace AlKhayal.Data.Authentication
{
    public sealed class SqliteUserStore : IUserStore { private readonly string _cs; public SqliteUserStore(string cs) { _cs = cs; }
        public async Task<UserRecord> FindByUsernameAsync(string username, CancellationToken ct) { using (var c = new SQLiteConnection(_cs)) return await c.QuerySingleOrDefaultAsync<UserRecord>(new CommandDefinition("SELECT Id, Username, DisplayName, PasswordHash, Role, IsActive FROM Users WHERE Username=@Username", new { Username = username }, cancellationToken: ct)); }
        public async Task<bool> IsEmptyAsync(CancellationToken ct) { using (var c = new SQLiteConnection(_cs)) return await c.ExecuteScalarAsync<long>(new CommandDefinition("SELECT COUNT(*) FROM Users", cancellationToken: ct)) == 0; }
        public Task<bool> TryCreateFirstAdminAsync(string username, string displayName, string passwordHash, CancellationToken ct) { ct.ThrowIfCancellationRequested(); using (var c = new SQLiteConnection(_cs)) { c.Open(); using (var tx = c.BeginTransaction(IsolationLevel.Serializable)) { if (c.ExecuteScalar<long>("SELECT COUNT(*) FROM Users", transaction:tx) != 0) { tx.Rollback(); return Task.FromResult(false); } var now=System.DateTime.UtcNow.ToString("o"); c.Execute("INSERT INTO Users (Username, DisplayName, PasswordHash, Role, IsActive, CreatedUtc, UpdatedUtc) VALUES (@Username,@DisplayName,@PasswordHash,'administrator',1,@Now,@Now)",new{Username=username,DisplayName=displayName,PasswordHash=passwordHash,Now=now},tx); tx.Commit(); return Task.FromResult(true); } } }
        public async Task<long> CreateAsync(string username, string displayName, string passwordHash, string role, CancellationToken ct) { using (var c = new SQLiteConnection(_cs)) { var now=System.DateTime.UtcNow.ToString("o"); return await c.ExecuteScalarAsync<long>(new CommandDefinition("INSERT INTO Users (Username, DisplayName, PasswordHash, Role, IsActive, CreatedUtc, UpdatedUtc) VALUES (@Username,@DisplayName,@PasswordHash,@Role,1,@CreatedUtc,@UpdatedUtc); SELECT last_insert_rowid();", new { Username = username, DisplayName=displayName, PasswordHash = passwordHash, Role=role, CreatedUtc = now, UpdatedUtc=now }, cancellationToken: ct)); } }
        public async Task UpdatePasswordHashAsync(long userId, string passwordHash, CancellationToken ct) { using (var c = new SQLiteConnection(_cs)) { var affected = await c.ExecuteAsync(new CommandDefinition("UPDATE Users SET PasswordHash=@PasswordHash, UpdatedUtc=@UpdatedUtc WHERE Id=@UserId", new { UserId=userId, PasswordHash=passwordHash, UpdatedUtc=System.DateTime.UtcNow.ToString("o") }, cancellationToken: ct)); if (affected != 1) throw new System.InvalidOperationException("The requested user no longer exists."); } }
        public async Task UpdateLastLoginAsync(long userId, System.DateTime utc, CancellationToken ct) { using (var c = new SQLiteConnection(_cs)) await c.ExecuteAsync(new CommandDefinition("UPDATE Users SET LastLoginUtc=@LastLoginUtc WHERE Id=@UserId", new { UserId=userId, LastLoginUtc=utc.ToString("o") }, cancellationToken: ct)); }
    }
    public sealed class SqliteSessionStore : ISessionStore { private readonly string _cs; public SqliteSessionStore(string cs) { _cs = cs; }
        public async Task SaveAsync(SessionRecord s, CancellationToken ct) { using (var c = new SQLiteConnection(_cs)) await c.ExecuteAsync(new CommandDefinition("INSERT INTO Sessions (Token, CsrfToken, UserId, ExpiresUtc, CreatedUtc) VALUES (@Token,@CsrfToken,@UserId,@ExpiresUtc,@CreatedUtc)", new { s.Token, s.CsrfToken, s.UserId, ExpiresUtc=s.ExpiresUtc.ToString("o"), CreatedUtc=System.DateTime.UtcNow.ToString("o") }, cancellationToken: ct)); }
        public async Task<SessionRecord> FindAsync(string token, CancellationToken ct) { using (var c = new SQLiteConnection(_cs)) return await c.QuerySingleOrDefaultAsync<SessionRecord>(new CommandDefinition("SELECT s.Token, s.CsrfToken, s.UserId, s.ExpiresUtc, u.Username, u.DisplayName, u.Role FROM Sessions s JOIN Users u ON u.Id=s.UserId WHERE s.Token=@Token AND u.IsActive=1", new { Token=token }, cancellationToken: ct)); }
        public async Task DeleteAsync(string token, CancellationToken ct) { using (var c = new SQLiteConnection(_cs)) await c.ExecuteAsync(new CommandDefinition("DELETE FROM Sessions WHERE Token=@Token", new { Token=token }, cancellationToken: ct)); }
    }
}
